mapper.select:
SELECT u.id, u.username, u.email, u.avatar, u.bio, u.status, u.last_active_at, u.created_at, COALESCE((SELECT COUNT(1) FROM t_note_item n WHERE n.user_id = u.id AND n.is_deleted = 0 AND n.is_public = 1), 0) AS noteCount, COALESCE((SELECT COUNT(1) FROM t_user_follow uf WHERE uf.following_id = u.id), 0) AS followerCount, COALESCE((SELECT COUNT(1) FROM t_user_follow uf WHERE uf.follower_id = u.id), 0) AS followingCount, (SELECT COUNT(1) FROM t_main_link m WHERE m.user_id = u.id) > 0 AS hasMainLink, false AS isFollowing FROM t_user u WHERE u.status = 1
AND u.id != #{currentUserId} AND u.id NOT IN ( SELECT following_id FROM t_user_follow WHERE follower_id = #{currentUserId} )
ORDER BY noteCount DESC, followerCount DESC, u.last_active_at DESC LIMIT #{limit}
